public class AccountSelector {
  public List<Account> selectByName(String name) {
    return [SELECT Id, Name FROM Account WHERE Name = :name];
  }
  public Account selectById(Id recordId) {
    return [SELECT Id, Name FROM Account WHERE Id = :recordId LIMIT 1];
  }
}

public class AccountService {
  private AccountSelector selector;
  public AccountService() {
    this.selector = new AccountSelector();
  }
  public String summarizeAccount(Id accountId) {
    Account record = selector.selectById(accountId);
    return record.Name;
  }
}

public class AccountDomain {
  private List<Account> records;
  public AccountDomain(List<Account> records) {
    this.records = records;
  }
  public void setDefaultRating() {
    for (Account record : records) {
      if (record.Rating == null) {
        record.Rating = 'Warm';
      }
    }
  }
}
